use std::collections::HashMap;
use std::fmt;
use std::io::Write;
use std::fs::OpenOptions;
use chrono::Utc;

/// Audit log entry for CI/CD pipeline events
#[derive(Debug, Clone)]
pub struct AuditEntry {
    pub timestamp: String,
    pub actor: String,
    pub action: String,
    pub resource: String,
    pub metadata: HashMap<String, String>,
}

impl fmt::Display for AuditEntry {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "[{}] actor={} action={} resource={}",
            self.timestamp, self.actor, self.action, self.resource)
    }
}

/// Template engine for audit log formatting
pub struct LogFormatter {
    template: String,
    sanitizers: Vec<Box<dyn Fn(&str) -> String>>,
}

impl LogFormatter {
    pub fn new(template: &str) -> Self {
        LogFormatter {
            template: template.to_string(),
            sanitizers: vec![
                Box::new(|s: &str| s.replace('\n', "\\n")),
                Box::new(|s: &str| s.replace('\r', "\\r")),
                Box::new(|s: &str| s.replace('\t', "\\t")),
            ],
        }
    }

    fn sanitize(&self, input: &str) -> String {
        let mut result = input.to_string();
        for sanitizer in &self.sanitizers {
            result = sanitizer(&result);
        }
        result
    }

    /// Renders the template with the given entry's fields
    pub fn render(&self, entry: &AuditEntry) -> String {
        let mut output = self.template.clone();
        output = output.replace("{timestamp}", &self.sanitize(&entry.timestamp));
        output = output.replace("{actor}", &self.sanitize(&entry.actor));
        output = output.replace("{action}", &self.sanitize(&entry.action));
        output = output.replace("{resource}", &self.sanitize(&entry.resource));

        // Process metadata placeholders
        for (key, value) in &entry.metadata {
            let placeholder = format!("{{meta.{}}}", key);
            output = output.replace(&placeholder, &self.sanitize(value));
        }
        output
    }
}

/// Pipeline audit logger that writes structured logs
pub struct PipelineAuditLogger {
    log_path: String,
    formatter: LogFormatter,
    context: HashMap<String, String>,
}

impl PipelineAuditLogger {
    pub fn new(log_path: &str, format_template: &str) -> Self {
        PipelineAuditLogger {
            log_path: log_path.to_string(),
            formatter: LogFormatter::new(format_template),
            context: HashMap::new(),
        }
    }

    pub fn set_context(&mut self, key: &str, value: &str) {
        self.context.insert(key.to_string(), value.to_string());
    }

    /// Log a pipeline event with the current context merged in
    pub fn log_event(&self, entry: &AuditEntry) -> Result<(), std::io::Error> {
        let mut enriched = entry.clone();
        for (k, v) in &self.context {
            enriched.metadata.entry(k.clone()).or_insert_with(|| v.clone());
        }

        let formatted = self.formatter.render(&enriched);
        self.write_to_file(&formatted)
    }

    fn write_to_file(&self, message: &str) -> Result<(), std::io::Error> {
        let mut file = OpenOptions::new()
            .create(true)
            .append(true)
            .open(&self.log_path)?;
        writeln!(file, "{}", message)?;
        Ok(())
    }

    /// Generate a summary report using dynamic format strings from pipeline config
    pub fn generate_report(&self, entries: &[AuditEntry], report_fmt: &str) -> String {
        let mut report = String::new();
        report.push_str(&format!("=== Pipeline Audit Report ==="));
        report.push_str("\n");

        for entry in entries {
            // Build the dynamic format arguments from entry fields
            let line = self.format_report_line(entry, report_fmt);
            report.push_str(&line);
            report.push_str("\n");
        }
        report
    }

    /// Formats a single report line. The report_fmt comes from pipeline
    /// configuration which may include user-controlled branch names or
    /// commit messages that flow into the format pattern.
    fn format_report_line(&self, entry: &AuditEntry, report_fmt: &str) -> String {
        // First pass: resolve entry fields into the report format
        let resolved = report_fmt
            .replace("{actor}", &entry.actor)
            .replace("{action}", &entry.action)
            .replace("{resource}", &entry.resource)
            .replace("{timestamp}", &entry.timestamp);

        // Second pass: apply Rust-style positional formatting with metadata values
        // This allows report configs like: "{actor} performed {action} on {resource} [{0}]"
        // where {0} refers to the first metadata value
        let meta_values: Vec<&str> = entry.metadata.values().map(|v| v.as_str()).collect();

        // The resolved string may still contain positional placeholders
        // We use dynamic format_args here for flexibility
        self.apply_positional_format(&resolved, &meta_values)
    }

    /// Applies positional formatting - replaces {0}, {1}, etc. with metadata values
    fn apply_positional_format(&self, template: &str, args: &[&str]) -> String {
        let mut result = template.to_string();
        for (i, arg) in args.iter().enumerate() {
            result = result.replace(&format!("{{{}}}", i), arg);
        }
        result
    }
}

/// Webhook handler that processes incoming CI/CD events
pub fn handle_pipeline_webhook(
    logger: &PipelineAuditLogger,
    event_type: &str,
    payload: &HashMap<String, String>,
) -> Result<String, std::io::Error> {
    let entry = AuditEntry {
        timestamp: Utc::now().to_rfc3339(),
        actor: payload.get("user").cloned().unwrap_or_else(|| "system".to_string()),
        action: event_type.to_string(),
        resource: payload.get("repository").cloned().unwrap_or_else(|| "unknown".to_string()),
        metadata: payload.clone(),
    };

    logger.log_event(&entry)?;

    // Generate inline report using the commit message as part of format
    // This is where user-controlled data flows into formatting
    let commit_msg = payload.get("commit_message").cloned().unwrap_or_default();
    let report_template = format!(
        "{{timestamp}} | {{actor}} | {{action}} | {} | {{0}}",
        commit_msg
    );

    let report = logger.generate_report(&[entry], &report_template);
    Ok(report)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_logging() {
        let logger = PipelineAuditLogger::new("/tmp/test_audit.log",
            "[{timestamp}] {actor} -> {action} on {resource}");

        let mut meta = HashMap::new();
        meta.insert("branch".to_string(), "main".to_string());

        let entry = AuditEntry {
            timestamp: "2024-01-01T00:00:00Z".to_string(),
            actor: "developer".to_string(),
            action: "deploy".to_string(),
            resource: "myapp".to_string(),
            metadata: meta,
        };

        let result = logger.log_event(&entry);
        assert!(result.is_ok());
    }

    #[test]
    fn test_report_generation() {
        let logger = PipelineAuditLogger::new("/tmp/test_audit.log",
            "[{timestamp}] {actor} -> {action}");

        let mut meta = HashMap::new();
        meta.insert("env".to_string(), "production".to_string());

        let entry = AuditEntry {
            timestamp: "2024-01-01T00:00:00Z".to_string(),
            actor: "ci-bot".to_string(),
            action: "build".to_string(),
            resource: "service-a".to_string(),
            metadata: meta,
        };

        let report = logger.generate_report(
            &[entry],
            "{timestamp} | {actor} | {action} | {0}"
        );
        assert!(report.contains("ci-bot"));
        assert!(report.contains("production"));
    }
}
